import type { SurveyAction, OptionSpec, ScaleSpec } from "./surveyActions.js";
import type { Methodology, MethodInputs } from "./studyMethodology.js";

/**
 * THE METHODOLOGY LIBRARY, WIDENED (2026-11-10) — market and consumer, advanced quantitative, academic and social
 * science, medical and healthcare, and qualitative research.
 *
 * Each entry is a full methodology like the first thirty-two: what it fits, its strengths and trade-offs, the sample
 * it needs, the analysis it leads to, and a `build` that writes a real starting questionnaire through the same gate
 * as every other edit. None is a name on a list: a method whose substance is an ANALYSIS (regression, factor,
 * cluster, key drivers, TURF) builds the measurement battery that analysis needs and names the analysis to run in
 * Data Analytics; a QUALITATIVE method builds the recruitment screener and consent, and its work happens in Research
 * Tools → Qualitative (`workflow`); a CLINICAL or epidemiological design builds the data-collection instrument for
 * planning and says, in `caution`, what the platform does not do — it is not a regulated clinical-trial system, it
 * does not randomise treatment, and nothing here is clinical validation or regulatory compliance.
 *
 * Imported by studyMethodology.ts (types only come back the other way), so the registry stays one list.
 */

/* the same blueprint helpers as studyMethodology.ts, kept local so the two files do not import each other's values */
const block = (title: string): SurveyAction => ({ op: "create_block", title } as SurveyAction);
type QExtra = { options?: OptionSpec[]; rows?: string[]; scale?: ScaleSpec; code?: string; required?: boolean; randomize?: boolean; validation?: { kind: string; value?: number }[] };
const q = (b: string, type: string, text: string, extra: QExtra = {}): SurveyAction => ({ op: "create_question", block: b, newPage: true, type, text, required: extra.required ?? true, ...extra } as SurveyAction);
const one = (b: string, text: string, options: OptionSpec[], extra: QExtra = {}) => q(b, "single_select", text, { options, ...extra });
const many = (b: string, text: string, options: OptionSpec[], extra: QExtra = {}) => q(b, "multi_select", text, { options, ...extra });
const grid = (b: string, text: string, rows: string[], scale: ScaleSpec, extra: QExtra = {}) => q(b, "matrix_single", text, { rows, scale, ...extra });
const num = (b: string, text: string, extra: QExtra = {}) => q(b, "numeric", text, extra);
const open = (b: string, text: string, required = false) => q(b, "long_text", text, { required });
const agree5: ScaleSpec = { points: 5, low: "Strongly disagree", high: "Strongly agree" };
const sat5: ScaleSpec = { points: 5, low: "Very dissatisfied", high: "Very satisfied" };
const likely5: ScaleSpec = { points: 5, low: "Definitely would not", high: "Definitely would" };
const imp5: ScaleSpec = { points: 5, low: "Not at all important", high: "Extremely important" };
const freq5: ScaleSpec = { points: 5, low: "Never", high: "Always" };
const P = (i: MethodInputs, fallback: string) => (i.product?.trim() || fallback);
const list = (xs: string[] | undefined, fallback: string[]) => (xs?.filter((x) => x.trim()).length ? xs.filter((x) => x.trim()) : fallback);
const none = (label = "None of these"): OptionSpec => ({ label, exclusive: true, anchor: true });
const other: OptionSpec = { label: "Other (please specify)", other: true, anchor: true };
const dk: OptionSpec = { label: "Don't know", exclusive: true, anchor: true };
const pnts: OptionSpec = { label: "Prefer not to say", exclusive: true, anchor: true };
const brandsOf = (i: MethodInputs) => list(i.brands, ["Brand A", "Brand B", "Brand C", "Brand D"]);
const AGE: OptionSpec[] = ["Under 18", "18–24", "25–34", "35–44", "45–54", "55–64", "65 or over", pnts];
const GENDER: OptionSpec[] = ["Woman", "Man", "Non-binary", { label: "In another way (please specify)", other: true, anchor: true }, pnts];
const EDU: OptionSpec[] = ["No formal schooling", "Primary", "Secondary", "Higher secondary / diploma", "Graduate", "Postgraduate or above", pnts];
const HEALTH5: OptionSpec[] = ["Excellent", "Very good", "Good", "Fair", "Poor"];
const demographics = (b = "About you"): SurveyAction[] => [block(b), one(b, "Which age group are you in?", AGE), one(b, "How do you describe your gender?", GENDER), one(b, "What is the highest level of education you have completed?", EDU)];
const consent = (b: string, about: string): SurveyAction => one(b, `This study is about ${about}. Taking part is voluntary, you can stop at any time, and your answers are kept confidential. Do you agree to take part?`, ["Yes, I agree to take part", { label: "No, I do not agree", exclusive: true }]);
const screener = (topic: string): SurveyAction[] => { const b = "Recruitment screener"; return [block(b), consent(b, topic), one(b, "Which age group are you in?", AGE), one(b, `How familiar are you with ${topic}?`, ["Very familiar", "Somewhat familiar", "Not very familiar", "Not at all familiar"]), one(b, "Have you taken part in a research interview or group discussion in the past six months?", ["Yes", "No"]), one(b, "Which of these would suit you?", ["A video call", "A phone call", "In person", "A text chat"]), open(b, "In a sentence or two, tell us about your experience with this topic.", true)]; };

/** a between-subjects split: one block per condition, each respondent sees exactly one (the assignment is recorded and exported) */
const cells = (conds: string[], what: string): SurveyAction[] => {
  const out: SurveyAction[] = [];
  for (const c of conds) out.push(block(c), one(c, `Thinking about ${c}${what ? ` for ${what}` : ""}, how appealing is it to you?`, [], { scale: { points: 5, low: "Not at all appealing", high: "Extremely appealing" } }), one(c, "How likely would you be to choose it?", [], { scale: likely5 }), one(c, "How clear was it?", [], { scale: { points: 5, low: "Not at all clear", high: "Very clear" } }), open(c, "What, if anything, stood out to you?"));
  out.push({ op: "create_randomizer", blocks: conds, show: 1, exact: true } as SurveyAction);
  return out;
};

type Sig = [RegExp, number][];
const m = (id: string, name: string, category: Methodology["category"], fit: string, strengths: string[], tradeoffs: string[], signals: Sig, inputs: Methodology["inputs"], sample: Methodology["sample"], loi: string, analysis: string[], alternatives: string[], build: Methodology["build"], extra: Partial<Pick<Methodology, "workflow" | "caution">> = {}): Methodology =>
  ({ id, name, category, fit, strengths, tradeoffs, signals, inputs, sample, loi, analysis, alternatives, build, ...extra });
const PRODUCT = (label: string, required = true): Methodology["inputs"][number] => ({ key: "product", label, kind: "text", required });
const QUAL = { workflow: { kind: "qualitative" as const, label: "Open Qualitative", note: "The interviews, transcripts, coding and themes are run in Research Tools → Qualitative. What is added here is the recruitment screener and consent." } };
const PLAN = "Research planning guidance and a data-collection instrument only. ResLens.ai is not a regulated clinical-trial or medical-records system: it does not randomise treatment, capture source data to regulatory standards, or provide clinical validation, ethics approval or regulatory compliance. Use your institution's approved protocol, ethics review and validated instruments.";

